<?php

namespace IPE\Extension;

/**
 * Interface for extensions whose configure script (generated by phpize) must be fixed.
 */
interface PatchesConfigureScript
{
    /**
     * Called after running phpize.
     *
     * @param non-empty-string $sourceDirectory
     *
     * @throws \IPE\Exception\IO
     *
     * @return void
     */
    public function patchConfigureScript($sourceDirectory);
}
